public class EvolutionTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(EvolutionTracker t) {
        return "gen=" + t.generation() + " best=" + t.bestFitness() + " ever=" + t.bestEverFitness();
    }

    public static void main(String[] args) {
        try {
            check("fitness counts the 1s", 3, EvolutionTracker.fitness(new int[]{1, 0, 1, 1}));

            EvolutionTracker small = new EvolutionTracker(6, 8, 42L);
            check("the seeded starting population (6 x 8, seed 42)", "gen=0 best=6 ever=6", describe(small));

            small.step(0.1);
            check("without elitism the live best can drop", "gen=1 best=5 ever=6", describe(small));
            small.run(5, 0.1);
            check("six generations later it has solved the problem", "gen=6 best=8 ever=8", describe(small));
            check("the solved genome is all ones", "[1, 1, 1, 1, 1, 1, 1, 1]",
                    java.util.Arrays.toString(small.bestGenome()));

            EvolutionTracker big = new EvolutionTracker(10, 12, 7L);
            big.run(12, 0.05);
            check("after 12 generations (seed 7)", "gen=12 best=11 ever=11", describe(big));

            EvolutionTracker wild = new EvolutionTracker(8, 10, 2024L);
            wild.run(4, 0.6);
            check("a wild mutation rate loses ground but not the record", "gen=4 best=7 ever=8",
                    describe(wild));

            EvolutionTracker replay = new EvolutionTracker(10, 12, 7L);
            replay.run(12, 0.05);
            check("the same seed replays the same run",
                    java.util.Arrays.toString(big.bestGenome()),
                    java.util.Arrays.toString(replay.bestGenome()));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

