/**
 * A tiny generational genetic algorithm that tracks the best fitness ever seen.
 */
public class EvolutionTracker {

    private final java.util.Random rng;
    private int[][] population;
    private int generation;
    private int bestEver;

    public EvolutionTracker(int populationSize, int geneLength, long seed) {
        this.rng = new java.util.Random(seed);
        this.population = new int[populationSize][geneLength];
        for (int i = 0; i < populationSize; i++) {
            for (int g = 0; g < geneLength; g++) {
                population[i][g] = rng.nextInt(2);
            }
        }
        this.generation = 0;
        this.bestEver = bestFitness();
    }

    public static int fitness(int[] genome) {
        int score = 0;
        for (int gene : genome) {
            score += gene;
        }
        return score;
    }

    public int bestIndex() {
        int best = 0;
        for (int i = 1; i < population.length; i++) {
            if (fitness(population[i]) > fitness(population[best])) {
                best = i;
            }
        }
        return best;
    }

    public int bestFitness() {
        return fitness(population[bestIndex()]);
    }

    public int bestEverFitness() {
        return bestEver;
    }

    public int generation() {
        return generation;
    }

    public int[] bestGenome() {
        int[] best = population[bestIndex()];
        return java.util.Arrays.copyOf(best, best.length);
    }

    private int tournament() {
        int a = rng.nextInt(population.length);
        int b = rng.nextInt(population.length);
        return fitness(population[a]) >= fitness(population[b]) ? a : b;
    }

    public void step(double mutationRate) {
        int size = population.length;
        int geneLength = population[0].length;
        int[][] next = new int[size][geneLength];
        for (int i = 0; i < size; i++) {
            int parentA = tournament();
            int parentB = tournament();
            int[] child = new int[geneLength];
            for (int g = 0; g < geneLength; g++) {
                child[g] = rng.nextBoolean() ? population[parentA][g] : population[parentB][g];
            }
            for (int g = 0; g < geneLength; g++) {
                if (rng.nextDouble() < mutationRate) {
                    child[g] = 1 - child[g];
                }
            }
            next[i] = child;
        }
        population = next;
        generation++;
        if (bestFitness() > bestEver) {
            bestEver = bestFitness();
        }
    }

    public void run(int generations, double mutationRate) {
        for (int i = 0; i < generations; i++) {
            step(mutationRate);
        }
    }
}
